SELECT DATE_TRUNC('MONTH', orders.ordered_at) AS ordered_at_month, stores.store_name AS store_name, COUNT(DISTINCT orders.order_id) AS orders FROM comparison_orders AS orders JOIN comparison_customers AS customers ON orders.customer_id = customers.customer_id JOIN comparison_stores AS stores ON orders.store_id = stores.store_id WHERE customers.lifetime_order_count > 1 GROUP BY DATE_TRUNC('MONTH', orders.ordered_at), stores.store_name ORDER BY 1, 2 LIMIT 5000